mapper.select:
select id, comment_id, post_id, content, stu_number, username, user_image,
       parent_id, reply_username, like_count, status, create_time
from chat_app.forum_comment


        and post_id = #{postId}


        and content like concat('%', #{content}, '%')


        and stu_number = #{stuNumber}


        and status = #{status}


order by create_time desc
